def k8s_namespace():
    '''Kubernetes namespace in which we run'''
    nsenv = os.getenv('ZENKO_K8S_NAMESPACE')
    if nsenv:
        return nsenv

    try:
        with open(os.path.join(SERVICEACCOUNT_PATH, 'namespace'), 'r') as nsfd:
            return nsfd.read()
    except IOError:
        pass

    raise RuntimeError('Unable to determine Zenko K8s namespace')

def zenko_helm_release():
    '''Zenko Helm release name'''
    rel = os.getenv('ZENKO_HELM_RELEASE')
    if not rel:
        raise RuntimeError('Unable to determine Zenko Helm release name')

    return rel

def zenko_s3_client():
    '''A Boto s3 client to the Zenko under test'''

    url = os.getenv('CLOUDSERVER_FRONT_ENDPOINT')
    if not url:
        url = 'http://{}-cloudserver:80'.format(zenko_helm_release())

    return boto3.client(
        service_name='s3',
        endpoint_url=url,
    )

def prometheus_client():
    '''A Prometheus client for the Prometheus server deployed with Zenko'''

    url = os.getenv('PROMETHEUS_ENDPOINT')
    if not url:
        url = 'http://{}-prometheus-server:80'.format(zenko_helm_release())

    return zenko_e2e.prometheus.client.PrometheusClient(prometheus_url=url)

def grafana_client():
    '''A Grafana client for the Grafana server deployed with Zenko'''

    user = os.getenv('GRAFANA_USER')
    if not user:
        user = 'admin'
    password = os.getenv('GRAFANA_PASSWORD')
    if not password:
        password = 'strongpassword'
    url = os.getenv('GRAFANA_ENDPOINT')
    if not url:
        url = 'http://{}-grafana:80'.format(zenko_helm_release())

    return zenko_e2e.grafana.client.GrafanaClient(
        user=user, password=password, endpoint=url)

def enable_ingest(kube, location):
    api_instance = client.CustomObjectsApi(kube)
    body = {"spec": {"rclone": {"triggerIngestion": True}}}
    return api_instance.patch_namespaced_custom_object(
        'zenko.io',
        'v1alpha1',
        conf.K8S_NAMESPACE,
        'cosmoses',
        location,
        body
    )

def get_job(kube_batch, location):
    jobs = kube_batch.list_namespaced_job(conf.K8S_NAMESPACE)
    for job in jobs.items:
        if location in job.metadata.name:
            return job.metadata.name
    return ""

def wait_for_job(kube_batch, location, timeout=180):
    _timestamp = time.time()
    while time.time() - _timestamp < timeout:
        try:
            enable_ingest(kube(), location)
            job = get_job(kube_batch, location)
            state = kube_batch.read_namespaced_job_status(
                job, conf.K8S_NAMESPACE)
            if state.status.succeeded:
                _log.debug("Finished with completed status")
                break
        except IndexError:
            # When the job hasn't yet been created, there is an index error
            pass
        except ApiException as err:
            _log.error("Exception when calling job status %s", err)
        _log.info("Waiting for job completion")
        time.sleep(1)
    else:
        _log.error('Initial ingestion did not complete in time')
    return state

