def wait_for_server(client):
    start_time = datetime.now()
    while True:
        try:
            r = client.get("core/")
            r.raise_for_status()
            return
        except Exception:
            time_elapsed = datetime.now() - start_time
            if time_elapsed.total_seconds() >= 60:
                print(f"time elapsed: {time_elapsed.total_seconds()}s")
                raise

